"""Global cleanup audits: metadata-only, bound snapshots and no local history."""
import json,re,time
from desktop_fixture import Peer,Desktop,expect,ROOT

out=ROOT/'artifacts/cleanup-records-ui'
def report_rows(count):
    return [dict(id=f'report-{n:04}',modified=1700000000+n,phase='completed',scope='task',selected_count=1,processed_count=1,removed_files=3,pending_files=0,service='inactive',issue=None) for n in range(count)]
def row(group,identifier):return group.locator('.cleanup-report-row').filter(has=group.page.get_by_text(identifier,exact=True))

with Peer(out/'peer-a') as a,Peer(out/'peer-b') as b:
    entries=report_rows(105)
    entries[104].update(phase='interrupted',removed_files=0,pending_files=1,service='failed',partial=True)
    entries[103].update(service='active');entries[102].update(service='failed')
    entries[101].update(phase=None,scope=None,issue='Cleanup report is unavailable or invalid')
    entries[100].update(phase='prepared',processed_count=0,removed_files=0,service='not-found')
    (a.root/'cleanup-reports-fixture.json').write_text(json.dumps(entries))
    (a.root/'cleanup-reports-incomplete').touch()
    (b.root/'cleanup-reports-fixture.json').write_text(json.dumps(report_rows(1)))
    alpha=a.profile('Alpha');alpha.update(username='arcnix-nosftp',auth='Password',private_key=None)
    config=a.config([alpha,b.profile('Beta')],out)
    host,port=b.data['address'].rsplit(':',1);config['config']['trusted_hosts'].append(dict(host=host,port=int(port),fingerprint=b.data['host_key_rsa_fingerprint']))
    with Desktop(out/f'desktop-{time.time_ns()}',config) as app:
        p=app.page;p.locator('.rail-tasks').click();p.get_by_role('button',name='Cleanup reports',exact=True).click()
        d=p.get_by_role('dialog',name='Connect to cleanup reports',exact=True);d.get_by_role('button',name='Read cleanup reports',exact=True).click();expect(d.locator('.form-error')).to_be_visible()
        for target in d.locator('.cleanup-report-target').all():target.click()
        d.get_by_role('textbox',name='SSH password or key passphrase',exact=True).first.fill('arcnix-test');d.get_by_role('textbox',name='Administrator password (optional)',exact=True).first.fill('fixture-admin-secret')
        d.get_by_role('button',name='Read cleanup reports',exact=True).click()
        groups=p.locator('.cleanup-report-group');expect(groups).to_have_count(2)
        alpha_group=groups.filter(has=p.get_by_text('Alpha',exact=True));beta_group=groups.filter(has=p.get_by_text('Beta',exact=True))
        for group in groups.all():expect(group.locator('.cleanup-query-state')).to_have_text('Cleanup report query completed',timeout=30000)
        expect(alpha_group.locator('.cleanup-report-row')).to_have_count(100);expect(beta_group.locator('.cleanup-report-row')).to_have_count(1)
        expect(alpha_group).to_contain_text('measurement is incomplete')
        expect(p.get_by_role('button',name='Cleanup reports',exact=True)).to_have_class(re.compile(r'.*\bactive\b.*'))
        for name in ['Recent batches','Server records','Record storage']:expect(p.get_by_role('button',name=name,exact=True)).not_to_have_class(re.compile(r'.*\bactive\b.*'))
        expect(row(alpha_group,'report-0103').locator('.cleanup-report-service')).to_have_text('Running')
        expect(row(alpha_group,'report-0102').locator('.cleanup-report-service')).to_contain_text('conflicts')
        expect(row(alpha_group,'report-0101').get_by_role('button',name='Inspect cleanup report',exact=True)).to_be_disabled()
        expect(row(alpha_group,'report-0100')).to_contain_text('execution unconfirmed')
        row(alpha_group,'report-0104').get_by_role('button',name='Inspect cleanup report',exact=True).click()
        body=alpha_group.locator('.cleanup-detail-body');expect(body).to_contain_text('unlink pending',timeout=30000)
        expect(body).to_contain_text('Quarantined directory identity is proven');expect(body).to_contain_text('File absent');expect(body).to_contain_text('Matches reviewed file')
        expect(body).to_contain_text('private [redacted] [redacted] detail');expect(body).to_contain_text('/var/lib/arcnix/record-cleanups/report-0104/report.json')
        alpha_group.locator('.cleanup-detail').scroll_into_view_if_needed()
        p.evaluate('() => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)))')
        app.screenshot('private-audit.png')
        assert not app.config.with_suffix('.tasks.json').exists()
        original=body.inner_text();sampled=alpha_group.locator('.cleanup-detail-sampled').inner_text()
        for flag,message in [('cleanup-reports-wrong-id','Cleanup detail identity changed'),('cleanup-reports-escaped-path','Cleanup detail escaped its original store'),('cleanup-reports-truncated','EOF')]:
            (a.root/flag).touch();alpha_group.get_by_role('button',name='Refresh report details',exact=True).click()
            expect(alpha_group.locator('.form-error')).to_contain_text(message,timeout=30000)
            expect(alpha_group.locator('.cleanup-query-state')).to_have_text('Report query failed; previous snapshots are retained',timeout=30000)
            expect(body).to_have_text(original);expect(alpha_group.locator('.cleanup-detail-sampled')).to_have_text(sampled);(a.root/flag).unlink()
        alpha_group.get_by_role('button',name='Refresh report details',exact=True).click();expect(alpha_group.locator('.cleanup-query-state')).to_have_text('Cleanup report query completed',timeout=30000)
        (a.root/'cleanup-reports-changed-root').touch();alpha_group.get_by_role('button',name='Refresh reports',exact=True).click()
        expect(alpha_group.locator('.form-error')).to_contain_text('Cleanup report page does not match',timeout=30000)
        expect(alpha_group.locator('.cleanup-query-state')).to_have_text('Report query failed; previous snapshots are retained',timeout=30000);expect(body).to_have_text(original)
        (a.root/'cleanup-reports-changed-root').unlink()
        alpha_group.get_by_role('button',name='More reports',exact=True).click();expect(alpha_group.locator('.cleanup-report-row')).to_have_count(5,timeout=30000);expect(alpha_group.locator('.cleanup-detail')).to_have_count(0)
        row(alpha_group,'report-0000').get_by_role('button',name='Inspect cleanup report',exact=True).click();expect(body).to_contain_text('Saved: removed',timeout=30000)
        alpha_group.get_by_role('button',name='Previous reports',exact=True).click();expect(alpha_group.locator('.cleanup-report-row')).to_have_count(100,timeout=30000)
        (b.root/'cleanup-reports-denied').touch();beta_group.get_by_role('button',name='Refresh reports',exact=True).click();expect(beta_group.locator('.cleanup-query-state')).to_have_text('Report query failed; previous snapshots are retained',timeout=30000)
        alpha_group.get_by_role('button',name='Refresh reports',exact=True).click();expect(alpha_group.locator('.cleanup-query-state')).to_have_text('Cleanup report query completed',timeout=30000);expect(beta_group.locator('.cleanup-report-row')).to_have_count(1)
        (b.root/'cleanup-reports-denied').unlink()
        # Forget while an authenticated detail read is in flight; its late
        # response must not repopulate private details or permit another query.
        (a.root/'cleanup-reports-slow').touch();row(alpha_group,'report-0104').get_by_role('button',name='Inspect cleanup report',exact=True).click()
        expect(alpha_group.locator('.cleanup-query-state')).to_have_text('Reading cleanup reports…')
        p.get_by_role('button',name='Forget report credentials',exact=True).click();expect(alpha_group.locator('.cleanup-detail')).to_have_count(0)
        time.sleep(1);expect(alpha_group.locator('.cleanup-detail')).to_have_count(0);expect(alpha_group.get_by_role('button',name='Refresh reports',exact=True)).to_be_disabled();(a.root/'cleanup-reports-slow').unlink()
        p.get_by_role('button',name='Connect to cleanup reports…',exact=True).click();d=p.get_by_role('dialog',name='Connect to cleanup reports',exact=True)
        expect(d.get_by_role('textbox',name='SSH password or key passphrase',exact=True).first).to_have_value('');expect(d.get_by_role('textbox',name='Administrator password (optional)',exact=True).first).to_have_value('')
        d.get_by_role('textbox',name='SSH password or key passphrase',exact=True).first.fill('incorrect');d.get_by_role('button',name='Read cleanup reports',exact=True).click()
        expect(alpha_group.locator('.cleanup-query-state')).to_have_text('Report query failed; previous snapshots are retained',timeout=30000);expect(alpha_group.locator('.cleanup-report-row')).to_have_count(100)
        p.get_by_role('button',name='Connect to cleanup reports…',exact=True).click();d=p.get_by_role('dialog',name='Connect to cleanup reports',exact=True)
        d.get_by_role('textbox',name='SSH password or key passphrase',exact=True).first.fill('arcnix-test');d.get_by_role('textbox',name='Administrator password (optional)',exact=True).first.fill('fixture-admin-secret');d.get_by_role('button',name='Read cleanup reports',exact=True).click()
        expect(alpha_group.locator('.cleanup-query-state')).to_have_text('Cleanup report query completed',timeout=30000)
        row(alpha_group,'report-0104').get_by_role('button',name='Inspect cleanup report',exact=True).click();expect(body).to_contain_text('unlink pending',timeout=30000)
        app.settings('General');p.get_by_role('button',name='简体中文',exact=True).click();expect(p.locator('.page-header-title')).to_have_text('常规');p.locator('.rail-tasks').click()
        expect(alpha_group.locator('.cleanup-detail')).to_have_count(0);expect(alpha_group.get_by_role('button',name='刷新报告',exact=True)).to_be_disabled()
        p.set_viewport_size(dict(width=900,height=700));assert p.evaluate('document.documentElement.scrollWidth <= innerWidth');app.screenshot('reports-chinese.png')
        assert not app.config.with_suffix('.tasks.json').exists();saved=app.config.read_text();assert all(s not in saved for s in ['report-0104','fixture-admin-secret','arcnix-test','unlink pending'])
        p.get_by_role('button',name='最近批次',exact=True).click();expect(p.locator('.cleanup-reports-page')).to_have_count(0);expect(p.locator('.task-entry')).to_have_count(0)

checks=['global report entry','one active Tasks subview','server selection validation','two independent SSH readers','sudo stdin without SFTP','100 plus 5 pagination','audit-only capacity warning','active service takes priority','failed service conflicts remain visible','invalid reports disable details','prepared is not completed','saved unlink intent differs from live absence','proven quarantine and remaining matching files','private error redaction','exact private report path','bad detail identity rejected','escaped quarantine rejected','truncated response rejected','failed refresh preserves detail and time','changed audit root rejected','pagination clears private detail','independent server failure','late detail ignored after forget','reconnect secrets empty','failed authentication preserves bound list','navigation drops credentials and private detail','no local task or secret persistence','Chinese narrow layout','recent view remains independent']
(out/'results.json').write_text(json.dumps(dict(passed=True,checks=checks),indent=2));print(f'{len(checks)} cleanup report UI checks passed')
